  name: "split_initcap_and_fold_render_pascal_case",
  ir_version: 1,
  internMode: "dict",
  ddl,
  rel_columns,
  rel_physical_names,
  rel_column_types,
  arrival_targets,
  boot: SUBSCRIBED_BOOT,
  final_select,
  host_plans,
  bind_plans,
